from google.cloud import logging

def write_log(log_name, log_entry):
    client = logging.Client()
    logger = client.logger(log_name)
    logger.log_struct(log_entry)

if __name__ == '__main__':
    log_name = 'my_log'
    log_entry = {'message': 'This is a structured log entry'}
    write_log(log_name, log_entry)

from google.cloud import logging

def get_client():
    return logging.Client()

def get_logger(client, log_name):
    return client.logger(log_name)

class LogEntry:
    def __init__(self, message, severity='INFO'):
        self.message = message
        self.severity = severity

    def to_dict(self):
        return {'message': self.message, 'severity': self.severity}
